102	 */
103	export const KnowledgeMoveBodySchema = z
104	  .object({
105	    source_scope: InsightScope,
106	    source_repository_name: z.string().regex(PROJECT_SLUG_REGEX).optional(),
107	    repository_name: z.string().regex(PROJECT_SLUG_REGEX),
108	  })
109	  .strict();
110	
111	// ---------------------------------------------------------------------------
112	// Knowledge — private helpers
113	// ---------------------------------------------------------------------------
114	
115	/**
116	 * Parses a raw string as a positive integer insight ID.
117	 *
118	 * Rejects:
119	 * - Non-numeric strings (NaN after Number())
120	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
121	 * - Zero or negative integers
122	 *
123	 * The decimal-point check is performed on the raw string before numeric
124	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
125	 *
126	 * @throws ApiError VALIDATION_ERROR for any rejected value.
127	 */
128	export function parseKnowledgeId(raw: string): number {
129	  // Reject strings containing a decimal point before numeric coercion —
130	  // this catches "1.5" and also "2.0", both of which the caller must treat
131	  // as non-integer IDs even though Number("2.0") === 2.
132	  if (raw.includes('.')) {
133	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
134	  }
135	  const n = Number(raw);
136	  if (!Number.isInteger(n) || n <= 0) {
137	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
138	  }
139	  return n;
140	}
141	
142	// ---------------------------------------------------------------------------
143	// Interface definitions
144	// ---------------------------------------------------------------------------
145	
146	/** Raw query parameters accepted by GET /api/knowledge. */
147	export interface KnowledgeListParams {
148	  scope?: string;
149	  category?: string;
150	  /** Comma-separated list of tags to filter by. */
151	  tags?: string;
152	  repository_name?: string;
153	  /** Full-text search query — delegates to searchInsights when present. */
154	  query?: string;
155	  limit?: number | string;
156	  offset?: number | string;
157	}
158	
159	// ---------------------------------------------------------------------------
160	// GET /api/knowledge
161	// ---------------------------------------------------------------------------
162	
163	/**
164	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
165	 *
166	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
167	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
168	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values throw
169	 *   `VALIDATION_ERROR`. Omitting `scope` (or passing `undefined`) returns all insights.
170	 * - `tags` is a comma-separated string that is split before being forwarded.
171	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
172	 *   are silently ignored (limit → undefined, offset → 0).
173	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
174	 *   to enforce a page size.
175	 */
176	export async function handleListKnowledge(
177	  ledgerRoot: string,
178	  params: KnowledgeListParams = {}
179	): Promise<Insight[]> {
180	  const manager = new KnowledgeStoreManager(ledgerRoot);
181	
182	  // Validate scope — reject any non-nullish string that is not a valid InsightScope value.
183	  // Absent scope (undefined) means "no filter" and is always allowed.
184	  let scope: 'global' | 'repository' | undefined;
185	  if (params.scope !== undefined) {
186	    const scopeResult = InsightScope.safeParse(params.scope);
187	    if (!scopeResult.success) {
188	      validationError(`Invalid scope value: '${params.scope}'. Must be 'global' or 'repository'.`);
189	    }
190	    scope = scopeResult.data;
191	  }
192	
193	  const category = params.category ?? undefined;
194	  const repository_name = params.repository_name ?? undefined;
195	
196	  // Split comma-separated tags; ignore empty segments.
197	  const tags =
198	    params.tags && params.tags.trim().length > 0
199	      ? params.tags
200	          .split(',')
201	          .map((t) => t.trim())
202	          .filter((t) => t.length > 0)
203	      : undefined;
204	
205	  // Coerce pagination params.
206	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
207	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
208	
209	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
210	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
211	
212	  if (params.query && params.query.trim().length > 0) {
213	    return manager.searchInsights(params.query.trim(), { scope, repository_name, category, tags, limit, offset });
214	  }
215	
216	  return manager.listInsights({ scope, category, tags, repository_name, limit, offset });
217	}
218	
219	// ---------------------------------------------------------------------------
220	// PATCH /api/knowledge/:id
221	// ---------------------------------------------------------------------------
222	
223	/**
224	 * Updates an existing knowledge insight identified by its numeric ID.
225	 *
